// ?Rva009B50F0DecodeToken@@YAHPAEHH@Z
// partial score=0.95 date=2026-09-10
// ?Rva009B50F0DecodeToken@@YAHPAEHH@Z
// Retail RVA 0x009B50F0, 270 bytes.  The VP6 token decoder is reached by the
// established block-decoder family at 0x009B5AF0/0x009B5DB0.  Its first
// probability selects the previous token; the remaining nine-byte row is a
// short arithmetic-coded tree.  The three-argument cdecl ABI is fixed by the
// callers and by the retail stack cleanup.
//
// The node[5] arm deliberately keeps the default result live across the
// decode call.  Retail materializes that result in EBX before the call and
// returns it through a shared tail when the decoded bit is zero.
// cl: /O2 /Ob0 /DNDEBUG /DWIN32 /D_WINDOWS /MD

int Rva009B4600DecodeBool(void *state, int probability);

int Rva009B50F0DecodeToken(unsigned char *ctx, int prev, int plane)
{
	void *state = ctx + 0x150;

	if (Rva009B4600DecodeBool(state, ctx[0x77C + 10 * plane + prev]))
		return prev;

	unsigned char *node = ctx + 0x7A4 + 9 * (10 * plane + prev);

	if (Rva009B4600DecodeBool(state, node[0]))
	{
		if (Rva009B4600DecodeBool(state, node[2]))
		{
			if (Rva009B4600DecodeBool(state, node[6]))
				return Rva009B4600DecodeBool(state, node[8]) + 8;
			return Rva009B4600DecodeBool(state, node[7]) + 5;
		}

		int result = 1;
		if (Rva009B4600DecodeBool(state, node[5]))
			result = 7;
		return result;
	}

	if (Rva009B4600DecodeBool(state, node[1]))
		return Rva009B4600DecodeBool(state, node[4]) + 3;
	return Rva009B4600DecodeBool(state, node[3]) * 2;
}
